package com.personal.meditation;
import android.content.*;import org.json.*;
final class Settings {
 static final String[] KEYS={"prepShort","prepLong","start","quarter","end"};static final int[] LENGTHS={90,600,150,150,900};
 final android.content.SharedPreferences prefs;Settings(Context context){prefs=context.getSharedPreferences("meditation_settings",0);}
 JSONObject get(){try{JSONObject out=new JSONObject().put("minutes",prefs.getInt("minutes",10));for(String role:new String[]{"bell","quarter"})out.put(role,prefs.getString(role,"soft_bell")).put(role+"Name",prefs.getString(role+"Name","Chosen audio file")).put(role+"HasCustom",!prefs.getString(role+"Uri","").isEmpty());JSONObject h=new JSONObject();for(int i=0;i<KEYS.length;i++)h.put(KEYS[i],new JSONObject().put("enabled",prefs.getBoolean(KEYS[i]+"Enabled",i!=2)).put("ms",prefs.getInt(KEYS[i]+"Ms",LENGTHS[i])));return out.put("vibrations",h);}catch(JSONException invalid){throw new IllegalStateException(invalid);}}
 boolean save(String raw){try{JSONObject data=new JSONObject(raw);Object minutes=data.get("minutes");if(!(minutes instanceof Integer)||(int)minutes<1||(int)minutes>240)return false;android.content.SharedPreferences.Editor edit=prefs.edit().putInt("minutes",(int)minutes);for(String role:new String[]{"bell","quarter"}){String sound=data.getString(role);if(!sound.equals("soft_bell")&&!sound.equals("warm_bowl")&&!sound.equals("gentle_chime")&&!sound.equals("temple_gong")&&!sound.equals("silent")&&!(sound.equals("custom")&&!prefs.getString(role+"Uri","").isEmpty()))return false;edit.putString(role,sound);}JSONObject h=data.getJSONObject("vibrations");for(int i=0;i<KEYS.length;i++){JSONObject value=h.getJSONObject(KEYS[i]);Object length=value.get("ms"),enabled=value.get("enabled");int maximum=i<2?900:5000;if(!(length instanceof Integer)||(int)length<50||(int)length>maximum||!(enabled instanceof Boolean))return false;edit.putInt(KEYS[i]+"Ms",(int)length).putBoolean(KEYS[i]+"Enabled",(boolean)enabled);}return edit.commit();}catch(JSONException|RuntimeException failed){return false;}}
 boolean custom(String role,String uri,String label){if(!role.equals("bell")&&!role.equals("quarter"))return false;return prefs.edit().putString(role,"custom").putString(role+"Uri",uri).putString(role+"Name",label).commit();}
}
